import { Component, input } from '@angular/core';
import { NzSpinModule } from 'ng-zorro-antd/spin';

/** hrm-spin — loading. Bọc content: <hrm-spin [spinning]="loading">...</hrm-spin> */
@Component({
  selector: 'hrm-spin',
  imports: [NzSpinModule],
  template: `
    <nz-spin [nzSpinning]="spinning()" [nzSize]="size()" [nzSimple]="simple()" [nzTip]="tip()">
      <ng-content />
    </nz-spin>
  `,
  host: { class: 'hrm-spin' },
})
export class HrmSpin {
  readonly spinning = input(true);
  readonly size = input<'small' | 'default' | 'large'>('default');
  readonly simple = input(false);
  readonly tip = input('');
}
